from openai import OpenAI
import os
import json
from dotenv import load_dotenv

load_dotenv()

class ChatBot:
    """聊天机器人基础版"""

    def __init__(self, name='小助手', system_prompt=None):
        self.name = name
        self.client = OpenAI(api_key=os.getenv('OPENAI_API_KEY'))
        self.model = 'gpt-3.5-turbo'

        # 默认人设
        default_system = f'你是一个名叫{name}的AI助手，友好、幽默、乐于助人。'
        self.system_prompt = system_prompt or default_system

        # 对话历史
        self.messages = [
            {'role': 'system', 'content': self.system_prompt}
        ]
        self.history = []  # 保存纯对话（不含system）

    def send(self, user_message, stream=False):
        """发送消息，支持流式输出"""
        self.messages.append({'role': 'user', 'content': user_message})
        self.history.append({'role': 'user', 'content': user_message})

        if stream:
            return self._send_stream()
        else:
            return self._send_normal()

    def _send_normal(self):
        response = self.client.chat.completions.create(
            model=self.model,
            messages=self.messages,
            temperature=0.7
        )
        reply = response.choices[0].message.content
        self._add_assistant_message(reply)
        return reply

    def _send_stream(self):
        """流式输出，用yield返回"""
        stream = self.client.chat.completions.create(
            model=self.model,
            messages=self.messages,
            temperature=0.7,
            stream=True
        )

        full_reply = ''
        for chunk in stream:
            delta = chunk.choices[0].delta
            if delta.content:
                full_reply += delta.content
                yield delta.content

        self._add_assistant_message(full_reply)

    def _add_assistant_message(self, content):
        self.messages.append({'role': 'assistant', 'content': content})
        self.history.append({'role': 'assistant', 'content': content})

    def clear(self):
        """清空对话"""
        self.messages = [{'role': 'system', 'content': self.system_prompt}]
        self.history = []

if __name__ == '__main__':
    bot = ChatBot(name='小明')
    print(f'🤖 {bot.name}: 你好！我是{bot.name}，有什么可以帮你的？')

    while True:
        user_input = input('👤 你: ')
        if user_input.lower() in ['退出', 'exit', 'quit']:
            print(f'🤖 {bot.name}: 再见！期待下次聊天~')
            break

        print(f'🤖 {bot.name}: ', end='', flush=True)
        for chunk in bot.send(user_input, stream=True):
            print(chunk, end='', flush=True)
        print()

