from openai import OpenAI
import os
import sys
import json
from dotenv import load_dotenv

sys.path.insert(0, os.path.dirname(__file__))

load_dotenv()

CHARACTERS = {
    'default': {'name': '小助手', 'avatar': '🤖', 'system_prompt': '你是一个友好的AI助手。'},
    'poet': {'name': '李白', 'avatar': '📜', 'system_prompt': '你是李白，爱写诗，说话文绉绉的。'},
    'teacher': {'name': '王老师', 'avatar': '👨‍🏫', 'system_prompt': '你是一位耐心的老师。'},
    'cat': {'name': '喵喵', 'avatar': '🐱', 'system_prompt': '你是一只猫咪，每句结尾加喵~。'}
}

HISTORY_DIR = 'conversations'
os.makedirs(HISTORY_DIR, exist_ok=True)

class FullChatBot:
    """完整版聊天机器人"""

    def __init__(self):
        self.client = OpenAI(api_key=os.getenv('OPENAI_API_KEY'))
        self.model = 'gpt-3.5-turbo'
        self.character_key = 'default'
        self.character = CHARACTERS['default']
        self.conversation_name = None
        self.messages = []
        self.history = []
        self._reset_messages()

    def _reset_messages(self):
        self.messages = [
            {'role': 'system', 'content': self.character['system_prompt']}
        ]
        self.history = []

    def switch_character(self, char_key):
        if char_key not in CHARACTERS:
            return False, f'没有找到角色：{char_key}'
        self.character_key = char_key
        self.character = CHARACTERS[char_key]
        self._reset_messages()
        return True, f'已切换到 {self.character["avatar"]} {self.character["name"]}'

    def send_message(self, user_input, stream=False):
        self.messages.append({'role': 'user', 'content': user_input})
        self.history.append({'role': 'user', 'content': user_input})

        if stream:
            return self._stream_response()
        else:
            return self._normal_response()

    def _normal_response(self):
        resp = self.client.chat.completions.create(
            model=self.model, messages=self.messages, temperature=0.7
        )
        reply = resp.choices[0].message.content
        self._save_reply(reply)
        return reply

    def _stream_response(self):
        stream = self.client.chat.completions.create(
            model=self.model, messages=self.messages, temperature=0.7, stream=True
        )
        full = ''
        for chunk in stream:
            if chunk.choices[0].delta.content:
                content = chunk.choices[0].delta.content
                full += content
                yield content
        self._save_reply(full)

    def _save_reply(self, content):
        self.messages.append({'role': 'assistant', 'content': content})
        self.history.append({'role': 'assistant', 'content': content})

    def save_conversation(self, name):
        path = os.path.join(HISTORY_DIR, f'{name}.json')
        data = {
            'name': name, 'character': self.character_key,
            'history': self.history, 'messages_count': len(self.history)
        }
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        self.conversation_name = name
        return True, f'对话已保存为: {name}'

    def load_conversation(self, name):
        path = os.path.join(HISTORY_DIR, f'{name}.json')
        if not os.path.exists(path):
            return False, f'找不到对话: {name}'
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        self.character_key = data['character']
        self.character = CHARACTERS.get(data['character'], CHARACTERS['default'])
        self.history = data['history']
        self.messages = [{'role': 'system', 'content': self.character['system_prompt']}]
        self.messages.extend(self.history)
        self.conversation_name = name
        return True, f'已加载对话: {name} ({len(self.history)}条消息)'

    def list_conversations(self):
        convs = []
        for f in os.listdir(HISTORY_DIR):
            if f.endswith('.json'):
                try:
                    with open(os.path.join(HISTORY_DIR, f), 'r', encoding='utf-8') as fp:
                        data = json.load(fp)
                    convs.append({'name': data['name'], 'char': data['character'], 'count': data['messages_count']})
                except:
                    pass
        return convs

    def handle_command(self, cmd):
        parts = cmd.strip().split(maxsplit=1)
        command = parts[0].lower()
        arg = parts[1] if len(parts) > 1 else ''

        if command in ['/help', '/?']:
            return self._help_text()
        elif command == '/clear':
            self._reset_messages()
            return '✅ 对话已清空'
        elif command == '/roles':
            return '🎭 可用角色：\n' + '\n'.join(
                f'  {c["avatar"]} {k} - {c["name"]}' for k, c in CHARACTERS.items()
            )
        elif command == '/role':
            ok, msg = self.switch_character(arg)
            return msg
        elif command == '/save':
            name = arg or '未命名'
            ok, msg = self.save_conversation(name)
            return msg
        elif command == '/load':
            ok, msg = self.load_conversation(arg)
            return msg
        elif command == '/list':
            convs = self.list_conversations()
            if not convs:
                return '📭 暂无历史对话'
            return '📁 历史对话：\n' + '\n'.join(
                f'  • {c["name"]} [{c["char"]}] - {c["count"]}条消息' for c in convs
            )
        elif command in ['/exit', '/quit']:
            return 'EXIT'
        else:
            return f'❓ 未知命令: {command}\n输入 /help 查看帮助'

    def _help_text(self):
        return """📖 命令帮助：
  /help       查看帮助
  /clear      清空对话
  /roles      列出所有角色
  /role <名>  切换角色
  /save <名>  保存对话
  /load <名>  加载对话
  /list       列出历史对话
  /exit       退出程序

直接输入文字就是和AI聊天~"""

if __name__ == '__main__':
    bot = FullChatBot()
    print('🧠 AI聊天机器人 v1.0')
    print('输入 /help 查看命令，直接输入开始聊天\n')

    avatar = bot.character['avatar']
    name = bot.character['name']
    print(f'{avatar} {name}: 你好！我是{name}，有什么可以聊的？')

    while True:
        try:
            user_input = input('👤 你: ')
        except (KeyboardInterrupt, EOFError):
            print('\n再见！')
            break

        if not user_input.strip():
            continue

        if user_input.startswith('/'):
            result = bot.handle_command(user_input)
            if result == 'EXIT':
                print('👋 再见！')
                break
            print(f'💻 {result}')
            continue

        avatar = bot.character['avatar']
        name = bot.character['name']
        print(f'{avatar} {name}: ', end='', flush=True)
        for chunk in bot.send_message(user_input, stream=True):
            print(chunk, end='', flush=True)
        print()

from openai import OpenAI
import os
import base64
from dotenv import load_dotenv

load_dotenv()
client = OpenAI(api_key=os.getenv('OPENAI_API_KEY'))

def encode_image(image_path):
    """把图片转成base64编码"""
    with open(image_path, 'rb') as f:
        return base64.b64encode(f.read()).decode('utf-8')

def analyze_image_url(image_url, question='请描述这张图片的内容'):
    """用URL分析图片"""
    response = client.chat.completions.create(
        model='gpt-4-turbo',
        messages=[
            {
                'role': 'user',
                'content': [
                    {'type': 'text', 'text': question},
                    {
                        'type': 'image_url',
                        'image_url': {'url': image_url}
                    }
                ]
            }
        ],
        max_tokens=1000
    )
    return response.choices[0].message.content

def analyze_image_local(image_path, question='请描述这张图片的内容'):
    """分析本地图片"""
    base64_image = encode_image(image_path)

    response = client.chat.completions.create(
        model='gpt-4-turbo',
        messages=[
            {
                'role': 'user',
                'content': [
                    {'type': 'text', 'text': question},
                    {
                        'type': 'image_url',
                        'image_url': {
                            'url': f'data:image/jpeg;base64,{base64_image}'
                        }
                    }
                ]
            }
        ],
        max_tokens=1000
    )
    return response.choices[0].message.content

def extract_text_from_image(image_path):
    """从图片中提取文字（OCR的一种方式）"""
    return analyze_image_local(
        image_path,
        '请提取图片中的所有文字，按原文格式输出。如果图片中没有文字，回复"无文字"。'
    )

if __name__ == '__main__':
    print('🖼️  图像理解示例')
    print('-' * 50)

    # 示例：描述一张网上的图片
    test_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/PNG_transparency_demonstration_1.png/280px-PNG_transparency_demonstration_1.png'

