}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
}

.tip {
    text-align: center;
    font-size: 12px;
    color: #999;
    margin-top: 8px;
}

/* 滚动条美化 */
.chat-messages::-webkit-scrollbar {
    width: 6px;
}

.chat-messages::-webkit-scrollbar-track {
    background: transparent;
}

.chat-messages::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 3px;
}

.chat-messages::-webkit-scrollbar-thumb:hover {
    background: #aaa;
}

// DOM元素
const messagesEl = document.getElementById('messages');
const inputEl = document.getElementById('messageInput');
const sendBtn = document.getElementById('sendBtn');
const clearBtn = document.getElementById('clearBtn');

let conversationId = 'default';
let isLoading = false;

// 自动调整输入框高度
inputEl.addEventListener('input', function() {
    this.style.height = 'auto';
    this.style.height = Math.min(this.scrollHeight, 120) + 'px';
});

// 发送消息
function sendMessage() {
    const message = inputEl.value.trim();
    if (!message || isLoading) return;

    // 添加用户消息
    addMessage(message, 'user');
    inputEl.value = '';
    inputEl.style.height = 'auto';

    // 显示打字指示器
    const typingEl = addTypingIndicator();
    isLoading = true;
    sendBtn.disabled = true;

    // 流式获取回复
    streamChat(message, typingEl);
}

function addMessage(text, role) {
    const messageDiv = document.createElement('div');
    messageDiv.className = `message ${role}-message`;

    const avatar = document.createElement('div');
    avatar.className = 'message-avatar';
    avatar.textContent = role === 'user' ? '👤' : '🤖';

    const content = document.createElement('div');
    content.className = 'message-content';
    content.innerHTML = formatMessage(text);

    messageDiv.appendChild(avatar);
    messageDiv.appendChild(content);
    messagesEl.appendChild(messageDiv);

    scrollToBottom();
    return content;
}

function addTypingIndicator() {
    const messageDiv = document.createElement('div');
    messageDiv.className = 'message ai-message';
    messageDiv.id = 'typing-indicator';

    const avatar = document.createElement('div');
    avatar.className = 'message-avatar';
    avatar.textContent = '🤖';

    const content = document.createElement('div');
    content.className = 'message-content';
    content.innerHTML = '<div class="typing-indicator"><span></span><span></span><span></span></div>';

    messageDiv.appendChild(avatar);
    messageDiv.appendChild(content);
    messagesEl.appendChild(messageDiv);
    scrollToBottom();

    return messageDiv;
}

function streamChat(message, typingEl) {
    const url = `/api/chat/stream?message=${encodeURIComponent(message)}&conversation_id=${conversationId}`;
    const eventSource = new EventSource(url);

    let aiContent = null;
    let fullText = '';

    eventSource.onmessage = function(event) {
        const data = JSON.parse(event.data);

        if (data.done) {
            // 完成
            eventSource.close();
            isLoading = false;
            sendBtn.disabled = false;
            return;
        }

        if (data.content) {
            // 第一次收到内容时，替换打字指示器
            if (!aiContent) {
                typingEl.querySelector('.message-content').innerHTML = '';
                aiContent = typingEl.querySelector('.message-content');
            }

            fullText += data.content;
            aiContent.innerHTML = formatMessage(fullText);
            scrollToBottom();
        }
    };

    eventSource.onerror = function() {
        eventSource.close();
        isLoading = false;
        sendBtn.disabled = false;

        if (!fullText) {
            typingEl.querySelector('.message-content').innerHTML = '⚠️ 出错了，请稍后重试';
        }
    };
}

function formatMessage(text) {
    // 简单的格式化
    return text
        .replace(/\n/g, '<br>')
        .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
}

function scrollToBottom() {
    messagesEl.scrollTop = messagesEl.scrollHeight;
}

// 清空对话
clearBtn.addEventListener('click', function() {
    if (!confirm('确定要清空对话吗？')) return;

    fetch('/api/clear', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ conversation_id: conversationId })
    }).then(() => {
        messagesEl.innerHTML = `
            <div class="message ai-message">
                <div class="message-avatar">🤖</div>
                <div class="message-content">
                    <p>对话已清空，有什么可以帮你的吗？</p>
                </div>
            </div>
        `;
    });
});

// 按钮点击发送
sendBtn.addEventListener('click', sendMessage);

// 回车发送
inputEl.addEventListener('keydown', function(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendMessage();
    }
});

// 页面加载后聚焦输入框
window.addEventListener('load', function() {
    inputEl.focus();
});

# app.py - AI学习助手后端主程序
import os
import sys
import json
import base64
from flask import Flask, render_template, request, jsonify, Response, send_from_directory
from werkzeug.utils import secure_filename

# 导入我们的模块
import db
import ai_service

app = Flask(__name__)
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024  # 16MB上传限制

# 上传目录
UPLOAD_FOLDER = 'uploads'
os.makedirs(UPLOAD_FOLDER, exist_ok=True)
os.makedirs('temp', exist_ok=True)

# 初始化数据库
db.init_db()

# ========== 页面路由 ==========

