# ========== 聊天API ==========

@app.route('/api/chat/stream', methods=['GET'])
def chat_stream_api():
    message = request.args.get('message', '')
    conv_id = request.args.get('conversation_id', type=int)

    if not message:
        return jsonify(error='message is required'), 400

    # 获取历史消息
    if conv_id:
        history = db.get_messages(conv_id)
        messages = [{'role': m['role'], 'content': m['content']} for m in history]
    else:
        conv_id = db.create_conversation()
        messages = []

    # 添加用户消息
    messages.append({'role': 'user', 'content': message})
    db.add_message(conv_id, 'user', message)

    def generate():
        full_reply = ''
        for content in ai_service.chat_stream(messages):
            full_reply += content
            yield f'data: {json.dumps({"content": content})}\n\n'

        # 保存AI回复
        db.add_message(conv_id, 'assistant', full_reply)
        yield f'data: {json.dumps({"done": True, "conversation_id": conv_id})}\n\n'

    return Response(generate(), mimetype='text/event-stream')

@app.route('/api/chat/image', methods=['POST'])
def chat_image():
    if 'image' not in request.files:
        return jsonify(error='no image'), 400

    file = request.files['image']
    question = request.form.get('question', '请描述这张图片并告诉我你学到了什么')

    # 读取图片并转base64
    image_data = file.read()
    image_b64 = base64.b64encode(image_data).decode('utf-8')

    def generate():
        full_reply = ''
        for content in ai_service.analyze_image_stream(image_b64, question):
            full_reply += content
            yield f'data: {json.dumps({"content": content})}\n\n'
        yield f'data: {json.dumps({"done": True})}\n\n'

    return Response(generate(), mimetype='text/event-stream')

