# ========== 语音API ==========

@app.route('/api/voice/speech-to-text', methods=['POST'])
def api_speech_to_text():
    if 'audio' not in request.files:
        return jsonify(error='no audio'), 400

    file = request.files['audio']
    filename = secure_filename(file.filename or 'audio.wav')
    filepath = os.path.join('temp', filename)
    file.save(filepath)

    try:
        text = ai_service.speech_to_text(filepath)
        return jsonify(text=text)
    finally:
        if os.path.exists(filepath):
            os.remove(filepath)

@app.route('/api/voice/text-to-speech', methods=['POST'])
def api_text_to_speech():
    data = request.json
    text = data.get('text', '')
    voice = data.get('voice', 'nova')

    import uuid
    filename = f'speech_{uuid.uuid4().hex[:8]}.mp3'
    filepath = os.path.join('temp', filename)

    ai_service.text_to_speech(text, filepath, voice)

    return jsonify(url=f'/temp/{filename}')

@app.route('/temp/<path:filename>')
def serve_temp(filename):
    return send_from_directory('temp', filename)

